/**
 * Jakarta Persistence entities representing data stored by TradeForm Service.
 *
 * <p>{@link com.lm.tradeformservice.entity.TradeFormEntity} maps a trade form to a database row.
 * Its ID is generated by the database, and its status is persisted as the enum name using {@code
 * EnumType.STRING}.
 *
 * <h2>Persisting an entity</h2>
 *
 * <p>Application code normally persists entities through {@link
 * com.lm.tradeformservice.repository.ITradeFormRepository}:
 *
 * <pre>{@code
 * TradeFormEntity entity = new TradeFormEntity(null, TradeFormStatus.PENDING);
 * TradeFormEntity saved = tradeFormRepository.save(entity);
 * Long generatedId = saved.getId();
 * }</pre>
 *
 * <p>The generated ID is {@code null} before insertion and is populated after a successful save.
 * Database access requires the PostgreSQL datasource configured for the application.
 */
package com.lm.tradeformservice.entity;
